import random, itertools
from src.paths import count_paths

def ref(rows, cols, blocked=set()):
    bs = set(blocked) if blocked is not None else set()
    if rows <= 0 or cols <= 0: return 0
    if (0,0) in bs or (rows-1,cols-1) in bs: return 0
    def _s(r,c):
        if r==rows-1 and c==cols-1: return 1
        t=0
        if r+1<rows and (r+1,c) not in bs: t+=_s(r+1,c)
        if c+1<cols and (r,c+1) not in bs: t+=_s(r,c+1)
        return t
    return _s(0,0)

random.seed(7)
bad=0; n=0
# 1) random small grids, random blocked subsets, incl. None
for rows in range(1,7):
  for cols in range(1,7):
    for p in (0.0,0.1,0.25,0.4,0.6,0.9,1.0):
      for trial in range(6):
        b={(r,c) for r in range(rows) for c in range(cols) if random.random()<p}
        a=ref(rows,cols,b); b2=count_paths(rows,cols,b); n+=1
        if a!=b2: bad+=1; print('MISMATCH',rows,cols,sorted(b),a,b2)
print('random grids checked:',n,'mismatches:',bad)

# 2) exhaustive over ALL blocked subsets of a 3x3 and 2x3 grid
for rows,cols in ((2,3),(3,3)):
  cells=[(r,c) for r in range(rows) for c in range(cols)]
  tot=0
  for k in range(len(cells)+1):
    for comb_ in itertools.combinations(cells,k):
      b=set(comb_); tot+=1
      assert ref(rows,cols,b)==count_paths(rows,cols,b), (rows,cols,b)
  print('exhaustive',rows,'x',cols,'subsets:',tot,'all match')

# 3) None blocked, non-set iterables, out-of-range coords, negative/zero dims
print('None blocked 4x4:', count_paths(4,4,None), '==', ref(4,4,None))
print('list blocked 4x4:', count_paths(4,4,[(1,1)]), '==', ref(4,4,[(1,1)]))
print('out-of-range:', count_paths(3,3,{(-1,-1),(9,9)}), '==', ref(3,3,{(-1,-1),(9,9)}))
print('mixed oor+real:', count_paths(4,4,{(9,9),(1,1)}), '==', ref(4,4,{(9,9),(1,1)}))
for d in (0,-1,-5):
  print('dims',d,':', count_paths(d,3), count_paths(3,d), '==', ref(d,3), ref(3,d))
print('default arg 3x3:', count_paths(3,3), '==', ref(3,3))
