export function createCache(loader, options = {}) {
  const store = new Map();
  return {
    async get(key, getOptions = {}) {
      if (store.has(key)) return store.get(key);
      const promise = Promise.resolve().then(() => loader(key, getOptions));
      store.set(key, promise.catch((err) => { store.delete(key); throw err; }));
      return store.get(key);
    },
    invalidate(key) { store.delete(key); },
    has(key) { return store.has(key); },
    size() { return store.size; },
    clear() { store.clear(); }
  };
}
